// DewfordTown_Gym (zone 25): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0031_room_DewfordTown_Gym.txt
// Story (chapter Ch2, Sapphire data/maps/DewfordTown_Gym/scripts.inc) after the "// ---- story" line (the room had no
// people): scripts 1-3, text lines 0-8. Brawly (uid 1), the Gym guide (uid 5), the statues' plaques and the three
// trainers (Hideki uid 2, Tessa uid 3, Laura uid 4: Black 2's eye-contact trainer script 3000 + id) are in
// data/story/ch2.json. Room origin (1,-1): zone tile = Sapphire tile + (1,-1).
// Darkness (dewford_dark, 2026-10-07): Sapphire's flash levels through h_flash_scale (command 0x1c9,
// b2tools/patches/zone_effects.py; the room is not in a/1/4/9, so Flash can't be used here, as in Sapphire). Every
// field load (map scripts 3/4, 0051_*_init.s) sets SetFlashLevel's circle (24/40/56/72 pixels for 0-3 trainers
// beaten); back from a battle (or a menu) it shows the circle from before and reserves script 5 = BrightenRoom (SE_SWITCH
// + animateflash, 1 pixel a field frame), which runs when the trainer's event has set its flag. The
// trainers stay Black 2 eye-contact trainers (their scripts are global). Brawly's win: AnimateFlashFullBrightness.
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_key_items.h"
#include "hoenn_story.inc"
#include "hoenn_rematch.inc"    // Emerald's rematches (em_gym_rematch: nothing in Sapphire / Ruby)

    ScriptEntry DG_Brawly           // 1: DewfordTown_Gym_EventScript_Brawly
    ScriptEntry DG_GymGuide         // 2: DewfordTown_Gym_EventScript_GymGuide
    ScriptEntry DG_GymStatue        // 3: DewfordTown_Gym_EventScript_LeftGymStatue / RightGymStatue
    ScriptEntry DG_FlashLoad        // 4: map scripts 3/4 (DewfordTown_Gym_OnTransition: SetFlashLevel)
    ScriptEntry DG_Brighten         // 5: reserved by 4 after a trainer's win (BrightenRoom)
    ScriptEntriesEnd
// ---- story
#define DG_BRAWLY 1

DG_Brawly:                          // trainerbattle_single TRAINER_BRAWLY, ..., BrawlyDefeated, NO_MUSIC
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_defeated TRAINER_BRAWLY, L_DG_BrawlyAgain
    TrainerSayMessage TRAINER_BRAWLY, 0, DG_BRAWLY  // I'm Brawly! Dewford's Gym Leader! ...
    ActorMsgClose                   // (NO_MUSIC: no eye-contact music)
    h_trainerbattle TRAINER_BRAWLY  // (in battle: "Whoah, wow! You made a much bigger splash...")
    VMCall Sub_DG_LightsOn          // DewfordTown_Gym_EventScript_BrawlyDefeated: AnimateFlashFullBrightness
    h_buffer_player
    SystemMsg 0, 2                  // {PLAYER} received the Knuckle Badge from Brawly.
    h_badge_fanfare                 // Common_EventScript_PlayGymBadgeFanfare
    MsgWinCloseAll
    h_msgbox_actor 1, DG_BRAWLY     // The Knuckle Badge makes all Pokémon up to Level 30... And, take this.
    h_closemessage
    h_setflag FLAG_DEFEATED_DEWFORD_GYM
    h_givebadge 2                   // setflag FLAG_BADGE02_GET
    h_addvar VAR_PETALBURG_GYM_STATE, 1
    h_set_gym_trainers 2            // Hideki, Tessa and Laura count as beaten
    h_goto_if_ne VAR_PETALBURG_GYM_STATE, 6, L_DG_GiveBulkUp
    h_clearflag FLAG_HIDE_PETALBURG_GYM_GUIDE   // Common_EventScript_ReadyPetalburgGymForBattle
    h_setflag FLAG_PETALBURG_MART_EXPANDED_ITEMS
L_DG_GiveBulkUp:                    // DewfordTown_Gym_EventScript_GiveBulkUp
    h_giveitem ITEM_TM08            // TM08 Bulk Up (Black 2's TM08 is Bulk Up too)
    h_goto_if_eq HLIB_RESULT, 0, L_DG_BagFull
    h_msgbox_actor 2, DG_BRAWLY     // That TM08 contains Bulk Up. ...
    h_setflag FLAG_RECEIVED_TM_BULK_UP
    h_release
L_DG_BagFull:                       // Common_EventScript_ShowBagIsFull
    h_msgbox_actor 8, DG_BRAWLY     // Too bad! The Bag is full...
    h_release
L_DG_BrawlyAgain:
    em_gym_rematch TRAINER_BRAWLY, DG_BRAWLY     // Emerald: after the Hall of Fame, a rematch (hoenn_rematch.inc)
    h_goto_if_unset FLAG_RECEIVED_TM_BULK_UP, L_DG_GiveBulkUp
    h_msgbox 3                      // I can see your talent becoming a giant wave...
    h_release

DG_GymGuide:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_buffer_player
    h_goto_if_set FLAG_DEFEATED_DEWFORD_GYM, L_DG_GuideVictory
    h_msgbox 4                      // Hey, how's it going, Champion-bound {PLAYER}? ...
    h_release
L_DG_GuideVictory:
    h_msgbox 5                      // Whoah! It's turned too bright in here! ...
    h_release

DG_GymStatue:                       // (lockall; MSGBOX_DEFAULT)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_goto_if_badge 2, L_DG_StatueCertified
    h_msgbox_info 6                 // Dewford Town Pokémon Gym
    h_closemessage
    h_release
L_DG_StatueCertified:
    h_buffer_player
    h_msgbox_info 7                 // Dewford Town Pokémon Gym / Brawly's Certified Trainers: {PLAYER}
    h_closemessage
    h_release
    .balign 4, 0

// ---- darkness (DewfordTown_Gym_EventScript_SetFlashLevel / BrightenRoom / AnimateFlash*)
#define DG_TARGET 0x401D                // the circle for the trainers beaten (h_flash_scale's scale; 0 = lights on)
#define DG_SHOWN 0x401E                 // the circle shown now (map-local works: 0 after entering)
#define SE_SWITCH SEQ_SE_FLD_127        /* [guess] Black 2's own Flash sound (its dark circle widening) */
#define DG_SCRIPT_BRIGHTEN 5

DG_FlashLoad:                           // field load: entering, back from a battle or a menu (screen still dark)
    h_goto_if_ne DG_SHOWN, 0, L_DG_FlashBack
    VMCall Sub_DG_FlashTarget
    WorkSet DG_SHOWN, DG_TARGET         // entering (or lit): SetFlashLevel's circle at once
    h_flash_scale DG_SHOWN
    VMHalt
L_DG_FlashBack:                         // back from a battle or a menu: the circle from before it. A trainer's flag is
    h_flash_scale DG_SHOWN              // set only after this (its battle script goes on), so BrightenRoom runs once
    RTReserveScript DG_SCRIPT_BRIGHTEN  // that event has ended (no light change after a menu)
    VMHalt

DG_Brighten:                            // DewfordTown_Gym_EventScript_BrightenRoom (Hideki, Tessa, Laura beaten)
    h_lock
    VMCall Sub_DG_FlashTarget
    h_goto_if_eq_var DG_SHOWN, DG_TARGET, L_DG_BrightenEnd   // NoLightChange
    h_playse SE_SWITCH
    VMCall Sub_DG_FlashGrow             // AnimateFlash1/2/3Trainers: animateflash 3/2/1
L_DG_BrightenEnd:
    h_release

Sub_DG_LightsOn:                        // DewfordTown_Gym_EventScript_AnimateFlashFullBrightness
    h_playse SE_SWITCH
    WorkSetConst DG_TARGET, FLASH_PX(200)   // animateflash 0 (Sapphire's level 0: 200 pixels, the whole screen)
    VMCall Sub_DG_FlashGrow
    h_flash_scale 0                     // SetLightsOn: setflashradius 0
    WorkSetConst DG_SHOWN, 0
    VMReturn

Sub_DG_FlashTarget:                     // SetFlashLevel + CheckHideki/Tessa/Laura: 0 trainers beaten = level 4 (24
// >>> emerald_rooms dewford_flash_jump (b2tools/emerald_rooms.py / emerald_gyms.py write this block on every run: edit the generator)
#ifdef HOENN_EMERALD
    VMJump Sub_DG_FlashTargetEm         // Emerald: six trainers, 8 pixels each
#endif
// <<< emerald_rooms dewford_flash_jump
    WorkSetConst DG_TARGET, 0           // pixels), each one 16 more (level 3/2/1: 40/56/72); lights on once the Gym
    h_goto_if_set FLAG_DEFEATED_DEWFORD_GYM, L_DG_TargetEnd  // is beaten (Sapphire: Brawly defeated; his win itself
    WorkSetConst DG_TARGET, FLASH_PX(24)                       // animates in DG_Brawly before this flag is set)
    h_goto_if_not_defeated TRAINER_HIDEKI, L_DG_TargetTessa
    WorkAdd DG_TARGET, FLASH_PX(16)
L_DG_TargetTessa:
    h_goto_if_not_defeated TRAINER_TESSA, L_DG_TargetLaura
    WorkAdd DG_TARGET, FLASH_PX(16)
L_DG_TargetLaura:
    h_goto_if_not_defeated TRAINER_LAURA, L_DG_TargetEnd
    WorkAdd DG_TARGET, FLASH_PX(16)
L_DG_TargetEnd:
    VMReturn

Sub_DG_FlashGrow:                       // animateflash: DG_SHOWN -> DG_TARGET, 1 pixel a field frame (Sapphire: 1 pixel
    WorkSet HLIB_TMP, DG_TARGET          // every 2 frames at 60 fps), and wait for it (the radii are 16 pixels apart)
    WorkSub HLIB_TMP, DG_SHOWN
    WorkDiv HLIB_TMP, FLASH_PX(1)
    h_flash_scale DG_TARGET, HLIB_TMP
    WorkSet DG_SHOWN, DG_TARGET
    WorkDiv HLIB_TMP, 16
    h_wait_work HLIB_TMP, 16
    VMReturn
    .balign 4, 0

// >>> emerald_rooms dewford_flash (b2tools/emerald_rooms.py / emerald_gyms.py write this block on every run: edit the generator)
#ifdef HOENN_EMERALD
#include "hoenn_trainers_emerald.h"
Sub_DG_FlashTargetEm:                   // pokeemerald DewfordTown_Gym_EventScript_SetFlashLevel + CountTrainersDefeated
    WorkSetConst DG_TARGET, 0
    h_goto_if_set FLAG_DEFEATED_DEWFORD_GYM, L_DG_EmTargetEnd
    WorkSetConst DG_TARGET, FLASH_PX(24)
    h_goto_if_not_defeated TRAINER_TAKAO, L_DG_EmTarget0
    WorkAdd DG_TARGET, FLASH_PX(8)
L_DG_EmTarget0:
    h_goto_if_not_defeated TRAINER_JOCELYN, L_DG_EmTarget1
    WorkAdd DG_TARGET, FLASH_PX(8)
L_DG_EmTarget1:
    h_goto_if_not_defeated TRAINER_LAURA, L_DG_EmTarget2
    WorkAdd DG_TARGET, FLASH_PX(8)
L_DG_EmTarget2:
    h_goto_if_not_defeated TRAINER_BRENDEN, L_DG_EmTarget3
    WorkAdd DG_TARGET, FLASH_PX(8)
L_DG_EmTarget3:
    h_goto_if_not_defeated TRAINER_CRISTIAN, L_DG_EmTarget4
    WorkAdd DG_TARGET, FLASH_PX(8)
L_DG_EmTarget4:
    h_goto_if_not_defeated TRAINER_LILITH, L_DG_EmTarget5
    WorkAdd DG_TARGET, FLASH_PX(8)
L_DG_EmTarget5:
L_DG_EmTargetEnd:
    VMReturn
    .balign 4, 0
#endif
// <<< emerald_rooms dewford_flash
